import{_ as t,a,o as n,a6 as s}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Create Contact Us","description":"","frontmatter":{"outline":false,"examples":[{"id":"create-contact-us-basic","title":"Submit an Enquiry","description":"Send a contact-form enquiry. Public — the storefront key is the only credential needed, and a customer token is not used.","query":"mutation createContactUs($input: createContactUsInput!) {\\n  createContactUs(input: $input) {\\n    contactUs {\\n      success\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"name\\": \\"John Doe\\",\\n    \\"email\\": \\"john@example.com\\",\\n    \\"contact\\": \\"+1234567890\\",\\n    \\"message\\": \\"I have a question about your products\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createContactUs\\": {\\n      \\"contactUs\\": {\\n        \\"success\\": true,\\n        \\"message\\": \\"Your inquiry has been submitted successfully. We will get back to you soon\\"\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"The name field is required.","cause":"name was omitted or sent empty","solution":"Send name as a non-empty string of at most 255 characters"},{"error":"The email field must be a valid email address.","cause":"The value is not a well-formed email","solution":"Validate the address client-side before submitting"},{"error":"The message field is required.","cause":"message was omitted or sent empty","solution":"Send message as a non-empty string"}]},{"id":"create-contact-us-minimal","title":"Without a Phone Number","description":"contact is optional. An enquiry submitted without it is accepted, which suits a form that only asks for an email reply.","query":"mutation createContactUs($input: createContactUsInput!) {\\n  createContactUs(input: $input) {\\n    contactUs {\\n      success\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"name\\": \\"Jane Smith\\",\\n    \\"email\\": \\"jane.smith@example.com\\",\\n    \\"message\\": \\"Do you ship to Ireland?\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createContactUs\\": {\\n      \\"contactUs\\": {\\n        \\"success\\": true,\\n        \\"message\\": \\"Your inquiry has been submitted successfully. We will get back to you soon\\"\\n      }\\n    }\\n  }\\n}\\n"},{"id":"create-contact-us-with-mutation-id","title":"With a Client Mutation ID","description":"Echo an identifier back with the response to correlate it with the originating form submission.","query":"mutation createContactUs($input: createContactUsInput!) {\\n  createContactUs(input: $input) {\\n    contactUs {\\n      success\\n      message\\n    }\\n    clientMutationId\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"name\\": \\"Jane Smith\\",\\n    \\"email\\": \\"jane.smith@example.com\\",\\n    \\"contact\\": \\"+0987654321\\",\\n    \\"message\\": \\"I would like to inquire about bulk order discounts for your clothing range.\\",\\n    \\"clientMutationId\\": \\"contact-form-001\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createContactUs\\": {\\n      \\"contactUs\\": {\\n        \\"success\\": true,\\n        \\"message\\": \\"Your inquiry has been submitted successfully. We will get back to you soon\\"\\n      },\\n      \\"clientMutationId\\": \\"contact-form-001\\"\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/shop/mutations/create-contact-us.md","filePath":"api/graphql-api/shop/mutations/create-contact-us.md","lastUpdated":1787725411000}'),o={name:"api/graphql-api/shop/mutations/create-contact-us.md"};function i(r,e,d,c,u,l){return n(),a("div",null,e[0]||(e[0]=[s('<h1 id="create-contact-us" tabindex="-1">Create Contact Us <a class="header-anchor" href="#create-contact-us" aria-label="Permalink to &quot;Create Contact Us&quot;">​</a></h1><p>Send a message through the storefront contact form. The store emails the enquiry to its configured contact address.</p><p>This mutation is public — the storefront key is the only credential, and a customer token changes nothing. The enquiry is not linked to an account, so identify the sender through <code>name</code> and <code>email</code> even for a signed-in customer.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>input</code></td><td><code>createContactUsInput!</code></td><td>Yes</td><td>Input object containing the contact-form fields.</td></tr></tbody></table><h3 id="input-fields-createcontactusinput" tabindex="-1">Input Fields (<code>createContactUsInput</code>) <a class="header-anchor" href="#input-fields-createcontactusinput" aria-label="Permalink to &quot;Input Fields (`createContactUsInput`)&quot;">​</a></h3><p>Every field is nullable in the schema — the requirement is enforced by server-side validation, not by the type, so omitting <code>name</code> is a valid query that fails at execution.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Max length</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>String</code></td><td>Yes</td><td>255</td><td>Sender&#39;s name.</td></tr><tr><td><code>email</code></td><td><code>String</code></td><td>Yes</td><td>255</td><td>Email address to reply to. Must be well-formed.</td></tr><tr><td><code>message</code></td><td><code>String</code></td><td>Yes</td><td>—</td><td>The enquiry body. No length cap is applied.</td></tr><tr><td><code>contact</code></td><td><code>String</code></td><td>No</td><td>50</td><td>Phone number. No format rule — any string up to 50 characters is accepted, and an enquiry without it still succeeds.</td></tr><tr><td><code>clientMutationId</code></td><td><code>String</code></td><td>No</td><td>—</td><td>Echoed back on the response.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>contactUs.success</code></td><td><code>Boolean</code></td><td><code>true</code> when the enquiry was handed to the mail queue.</td></tr><tr><td><code>contactUs.message</code></td><td><code>String</code></td><td>Translated confirmation text.</td></tr><tr><td><code>clientMutationId</code></td><td><code>String</code></td><td>Echoed from the input when provided.</td></tr></tbody></table><p>Nothing addressable comes back — no id, no record to fetch. The enquiry leaves as an email, so a client cannot list, track, or follow up on submissions. Show the confirmation and treat the exchange as finished.</p><h2 id="success-can-be-false-without-an-error" tabindex="-1"><code>success</code> Can Be <code>false</code> Without an Error <a class="header-anchor" href="#success-can-be-false-without-an-error" aria-label="Permalink to &quot;`success` Can Be `false` Without an Error&quot;">​</a></h2><p>The enquiry is <strong>queued</strong>, not sent inline, so the response confirms the hand-off rather than delivery. If queueing itself fails the mutation still resolves normally, with no <code>errors</code> array, and returns:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Unable to send your inquiry at this time. Please try again later&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Read <code>success</code> before showing a confirmation — the absence of <code>errors</code> does not mean the enquiry got through. Delivery after a successful queue is not reported at all.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Required fields are validated server-side. A failure surfaces as a top-level <code>errors</code> entry with every problem joined into one string, so a submission missing both <code>name</code> and <code>message</code> returns <code>&quot;The name field is required. The message field is required.&quot;</code> rather than two separate entries.</p><h2 id="guard-the-form-yourself" tabindex="-1">Guard the Form Yourself <a class="header-anchor" href="#guard-the-form-yourself" aria-label="Permalink to &quot;Guard the Form Yourself&quot;">​</a></h2><p>The storefront key is the only credential, and there is no uniqueness rule — the same message can be submitted repeatedly. An unprotected public form invites automated submissions, so rate limiting or a captcha in front of it is the client&#39;s responsibility; the API applies no additional check.</p><h2 id="same-operation-over-rest" tabindex="-1">Same Operation Over REST <a class="header-anchor" href="#same-operation-over-rest" aria-label="Permalink to &quot;Same Operation Over REST&quot;">​</a></h2><p><a href="/api/rest-api/shop/contact-us/submit-contact-us.html"><code>POST /api/shop/contact-us</code></a> takes the same four fields and returns the same <code>success</code> and <code>message</code>. Only the request shape differs.</p>',21)]))}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
